pub fn bin_kind_to_u8(v: BinKind) -> u8 {
    match v {
        BinKind::Add => 0,
        BinKind::Sub => 1,
        BinKind::Mul => 2,
        BinKind::Lt => 3,
        BinKind::Le => 4,
        BinKind::Gt => 5,
        BinKind::Ge => 6,
        BinKind::StrictEq => 7,
        BinKind::StrictNe => 8,
        BinKind::BitAnd => 9,
        BinKind::BitOr => 10,
        BinKind::BitXor => 11,
    }
}

